<?php namespace App\Services;
final class UploadService { public static function projectImage(array $file):?string{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if($file['error']!==UPLOAD_ERR_OK||$file['size']>2*1024*1024)throw new \RuntimeException('Image upload failed or exceeds 2MB.');$f=new \finfo(FILEINFO_MIME_TYPE);$mime=$f->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new \RuntimeException('Only JPG, PNG and WEBP images are allowed.');$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$target=ROOT.'/public/uploads/projects/'.$name;if(!move_uploaded_file($file['tmp_name'],$target))throw new \RuntimeException('Unable to store image.');return $name;} }
